const PROTECTED_WORDS = new Set([
  "IN",
  "Disaster AI India",
  "FastAPI",
  "React",
  "Vite",
  "Leaflet",
  "OpenStreetMap",
  "Google OR-Tools",
  "OR-Tools",
  "OSRM",
  "USGS",
  "GDACS",
  "NDMA",
  "JWT",
  "PBKDF2",
  "PWA",
  "ETA",
]);

function normalizeLocal(value) {
  return String(value ?? "").replace(/\s+/g, " ").trim();
}

function preserveCase(source, translated) {
  if (!translated) return source;
  if (source === source.toUpperCase() && /[A-Z]/.test(source)) {
    return translated;
  }
  return translated;
}

function translateByWords(text, language) {
  const dictionary = WORD_TRANSLATIONS[language];
  if (!dictionary) return text;

  const words = String(text).match(/[A-Za-z]+(?:['’.-][A-Za-z]+)*/g) || [];
  if (!words.length) return text;

  // Never produce awkward code-mixed sentences. Word-level fallback is used
  // only when every meaningful English word in the short label is known.
  for (const word of words) {
    const key = word.toLowerCase();
    if (PROTECTED_WORDS.has(word) || PROTECTED_WORDS.has(key)) continue;
    if (!dictionary[key]) return text;
  }

  let changed = false;
  const output = String(text).replace(/[A-Za-z]+(?:['’.-][A-Za-z]+)*/g, (word) => {
    const key = word.toLowerCase();
    if (PROTECTED_WORDS.has(word) || PROTECTED_WORDS.has(key)) return word;
    const translated = dictionary[key];
    if (!translated) return word;
    changed = true;
    return preserveCase(word, translated);
  });

  return changed ? output : text;
}

export function translateLocal(text, language) {
  const source = normalizeLocal(text);
  if (!source || language === "en" || PROTECTED_WORDS.has(source)) {
    return source;
  }

  const phrase = COMMON_PHRASES[language]?.[source];
  if (phrase && phrase !== source) return phrase;

  const exact = TRANSLATIONS[language]?.[source];
  if (exact && exact !== source) return exact;

  // Word-level fallback is intentionally limited to short UI labels.
  // Longer sentences remain English unless they have a reviewed phrase
  // translation, avoiding awkward mixed-language sentences.
  const wordCount = source.split(/\s+/).filter(Boolean).length;
  if (wordCount <= 5) {
    return translateByWords(source, language);
  }

  return source;
}

export const PROTECTED_TEXT = PROTECTED_WORDS;
